Definition tfirst (L : alayout) (T : list bq) (tf0 : Z) : Z := match T with [] => tf0 | x :: _ => baddr L x end.
Definition tlast (L : alayout) (T : list bq) (tl0 : Z) : Z := List.last (map (baddr L) T) tl0.

